    'Nonthaburi': ['นนทบุรี', 'นบ'], 'Pathum Thani': ['ปทุมธานี', 'ปท'], 'Pattani': ['ปัตตานี', 'ปน'], 'Phang Nga': ['พังงา', 'พง'],
