  const rural = ({ abbr, region, road }, dflt) => {
    const m = String(road || '').trim().match(/^(?:([ก-ฮ]{2})\.?\s*)?(\d{3,4})$/);
    const ab = String(abbr || (m && m[1]) || ABBR[String(region || '').trim()] || '').trim().replace(/\.$/, '');
    return { ab: ab ? ab + '.' : '', num: m ? m[2] : dflt };
  };
  const THL = "'Noto Sans Thai',sans-serif";                          // loopless Thai of the rural-road plates
  const LEM = "'RG2014 Series EM','RG2014 Series E',sans-serif";      // the heavy painted digits of the old stones
